#!/usr/bin/env node
import { execFileSync } from "node:child_process";
import { chmodSync, cpSync, existsSync, mkdirSync, readdirSync, readFileSync, rmSync, statSync, writeFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const repoRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const sourceRoot = path.resolve(process.env.WW2_SOURCE_ROOT ?? path.join(repoRoot, "..", "ww-2"));
const outputRoot = path.join(repoRoot, "engines", "ww-2-runtime");

const requiredFiles = [
  "requirements.txt",
  "tools/ww",
  "tools/batch.py",
  "tools/compile_angles.py",
  "tools/compile_spec.py",
  "tools/context.py",
  "tools/format_contracts.py",
  "tools/generate.py",
  "tools/lfs_agent.py",
  "tools/lfs_brief.py",
  "tools/lfs_chief.py",
  "tools/lfs_fix.py",
  "tools/lfs_outline.py",
  "tools/lfs_policy.py",
  "tools/lfs_semantic.py",
  "tools/lfs_tripwire.py",
  "tools/lfs_v41.py",
  "tools/lfs_verify.py",
  "tools/preflight.py",
  "tools/research.py",
  "tools/research_cards.py",
  "tools/strategy_build.py",
  "tools/strategy_contract.py",
  "tools/ww_artifacts.py",
  "tools/ww_paths.py",
  "components/dr-opener-primal-recognition.md",
  "components/dr-system.md",
  "components/hook-types.md",
  "components/lfs-briefing-template.md",
  "components/lfs-headline-guide.md",
  "components/lfs-prompt-engine.md",
  "components/product-reveal-prompt.md",
  "components/tera-lfs-close.md",
];

const requiredDirs = [
  "components/lfs-formats",
  "formats/lfs",
];

main();

function main() {
  assertDirectory(sourceRoot, "WW2_SOURCE_ROOT");
  assertRequiredInputs();

  rmSync(outputRoot, { recursive: true, force: true });
  mkdirSync(outputRoot, { recursive: true });

  const copiedFiles = [];
  const copiedDirs = [];

  for (const relativePath of requiredFiles) {
    if (!existsSync(path.join(sourceRoot, relativePath))) continue;
    copyPath(relativePath);
    copiedFiles.push(relativePath);
  }

  for (const relativePath of requiredDirs) {
    copyPath(relativePath);
    copiedDirs.push(relativePath);
  }

  chmodSync(path.join(outputRoot, "tools", "ww"), 0o755);
  writeManifest(copiedFiles, copiedDirs);
  writeReadme(copiedFiles, copiedDirs);

  console.log(`Created ww-2 runtime bundle at ${path.relative(repoRoot, outputRoot)}`);
  console.log(`Included ${copiedFiles.length} files and ${copiedDirs.length} directories from ${sourceRoot}`);
}

function assertDirectory(directory, label) {
  if (!existsSync(directory) || !statSync(directory).isDirectory()) {
    throw new Error(`${label} does not exist or is not a directory: ${directory}`);
  }
}

function assertRequiredInputs() {
  const missing = [
    ...requiredFiles.filter((relativePath) => !existsSync(path.join(sourceRoot, relativePath))),
    ...requiredDirs.filter((relativePath) => !existsSync(path.join(sourceRoot, relativePath))),
  ];
  const hardMissing = missing.filter((relativePath) => relativePath !== "components/hook-types.md");
  if (hardMissing.length) {
    throw new Error(`Cannot build ww-2 runtime bundle; missing required paths:\n${hardMissing.join("\n")}`);
  }
}

function copyPath(relativePath) {
  const source = path.join(sourceRoot, relativePath);
  const target = path.join(outputRoot, relativePath);
  mkdirSync(path.dirname(target), { recursive: true });
  cpSync(source, target, { recursive: true, dereference: true });
}

function writeManifest(copiedFiles, copiedDirs) {
  const manifest = {
    generatedAt: new Date().toISOString(),
    sourceRoot,
    sourceGitCommit: gitOutput(["rev-parse", "HEAD"]) ?? null,
    purpose: "Minimal ww-2 runtime required by hosted WWX research, strategy, and LFS4.1 workflows.",
    excludedByDesign: [
      "products",
      "batches",
      "reports",
      "research-corpus",
      "uploads",
      "local environment files",
      "desktop cache files",
      "video and landing-page workflows",
      "unrelated tools",
    ],
    files: copiedFiles,
    directories: directoryFiles(copiedDirs),
  };
  writeFileSync(path.join(outputRoot, "RUNTIME_BUNDLE_MANIFEST.json"), `${JSON.stringify(manifest, null, 2)}\n`);
}

function writeReadme(copiedFiles, copiedDirs) {
  const body = [
    "# ww-2 Runtime Bundle",
    "",
    "This is a curated runtime subset of `ww-2`, generated by `pnpm engine:bundle`.",
    "",
    "It includes only the Python entrypoints, imported support modules, LFS/research/strategy prompt assets, format contracts, and Python requirements used by the hosted WWX blackbox runtime.",
    "",
    "It intentionally excludes product data, batch outputs, local reports, logs, caches, uploads, broad workflow experiments, and unrelated tools.",
    "",
    "## Included Files",
    "",
    ...copiedFiles.map((file) => `- \`${file}\``),
    "",
    "## Included Directories",
    "",
    ...copiedDirs.map((directory) => `- \`${directory}\``),
    "",
  ].join("\n");
  writeFileSync(path.join(outputRoot, "README.md"), body);
}

function directoryFiles(directories) {
  return Object.fromEntries(directories.map((directory) => [directory, listFiles(path.join(outputRoot, directory), directory)]));
}

function listFiles(root, prefix) {
  const entries = [];
  for (const entry of readdirSync(root, { withFileTypes: true })) {
    const relativePath = path.join(prefix, entry.name);
    const fullPath = path.join(outputRoot, relativePath);
    if (entry.isDirectory()) {
      entries.push(...listFiles(fullPath, relativePath));
    } else {
      entries.push(relativePath);
    }
  }
  return entries.sort();
}

function gitOutput(args) {
  try {
    return execFileSync("git", ["-C", sourceRoot, ...args], { encoding: "utf8" }).trim();
  } catch {
    return null;
  }
}
